class ApiService {
  private readonly umeBackend: string;

  private readonly token: string;

  public getPlantLink = async (plant: number): Promise<string | undefined> => {
    try {
      const response = await axios.get(
        `${this.umeBackend}/downtime/getPlantLink/${plant}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      return response.data;
    } catch (error) {
      console.error('Error fetching support URL from backend:', error);
      return undefined;
    }
  };

  public fetchSupportUrlFromBackend = async (
    path: string,
  ): Promise<string | null> => {
    try {
      const encodedPath = encodeURIComponent(path);
      const response = await axios.get<{ supportUrl: string | null }>(
        `${this.umeBackend}/app-page-list/find-support-url?path=${encodedPath}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      return response.data.supportUrl ?? null;
    } catch (error) {
      console.error('Error fetching support URL from backend:', error);
      return null;
    }
  };

  constructor(umeBackend: string, token: string) {
    this.umeBackend = umeBackend;
    this.token = token;
  }

  /**
   * Fetches favorite screen IDs for the current user from the backend.
   * @returns Array of favorite screen IDs.
   */
  public async fetchFavoriteScreens(): Promise<Array<string | number>> {
    const userId = localStorage.getItem('userId');
    const { plant } = useLocalizationStore();
    if (!userId || !plant) return [];
    try {
      const url = `${this.umeBackend}/user-preference/${plant}/${userId}/FAVORITES`;
      const response = await axios.get(url, {
        headers: { authorization: `Bearer ${this.token}` },
      });
      if (response.data.length > 0 && response.data[0].userCriteria) {
        // Parse as IDs (number if possible, else string)
        return response.data[0].userCriteria
          .split(';')
          .filter(Boolean)
          .map((id: string) => (isNaN(Number(id)) ? id : Number(id)));
      }
      return [];
    } catch (error) {
      console.error('Failed to fetch favorites from API', error);
      return [];
    }
  }

  /**
   * Saves favorite screen IDs for the current user to the backend.
   * @param ids - Array of screen IDs to save as favorites.
   */
  public async saveFavoriteScreens(ids: Array<string | number>): Promise<void> {
    const userId = localStorage.getItem('userId');
    const { plant } = useLocalizationStore();
    if (!userId || !plant) {
      console.warn('Missing userId or plant', { userId, plant });
      return;
    }
    try {
      const preferences = [
        {
          plant: Number(plant),
          action: 'FAVORITE',
          appName: 'FAVORITES',
          userCriteria: ids.join(';'),
          user: { userId: Number(userId) },
        },
      ];
      await axios.post(`${this.umeBackend}/user-preference/save`, preferences, {
        headers: { authorization: `Bearer ${this.token}` },
      });
    } catch (error) {
      console.error('Failed to save favorites to API', error);
    }
  }

  async getMenuItems(): Promise<Array<MenuList>> {
    try {
      const response = await axios.get(`${this.umeBackend}/app-list`, {
        headers: {
          authorization: `Bearer ${this.token}`,
        },
      });
      return response.data as Array<MenuList>;
    } catch (error) {
      console.error('Error fetching menu items:', error);
      throw error;
    }
  }

  public async getPlantDetails(plant: number): Promise<any> {
    try {
      const baseUrl = this.umeBackend.replace(/\/ume-be$/, '');
      const response = await axios.get(
        `${baseUrl}/plt-hry-api/plant/getPlantById/${plant}`,
        {
          headers: {
            authorization: `Bearer ${this.token}`,
          },
        },
      );
      const plantDetails = response.data;
      return plantDetails;
    } catch {
      console.error('Error fetching plant details');
      return null;
    }
  }
}

