export const useLocalizationStore = defineStore('localizationStore', {
  state: () => ({
    availableLanguages: storedAvailableLanguages,
    plant:
      JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes?.plant ??
      (undefined as number | undefined),
    plantLocalization: undefined as string | undefined,
    plantTimezone:
      JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes
        ?.timezone ?? '',
    userSelectedLocalization:
      sessionStorage.getItem('userSelectedLocalization') ?? undefined,
    userStoredLocalization: ((): string | undefined => {
      try {
        const locale =
          JSON.parse(localStorage?.userAttributes ?? '{}')?.userAttributes
            ?.locale ?? undefined;
        return locale ? locale.toLocaleUpperCase() : undefined;
      } catch {
        return undefined;
      }
    })(),
  }),

  getters: {
    localization(state): string {
      const supported = new Set(
        state.availableLanguages.map((lang) => lang.value),
      );
      if (
        state.userSelectedLocalization &&
        supported.has(state.userSelectedLocalization)
      ) {
        return state.userSelectedLocalization;
      }

      const pathSegments = globalThis.location.pathname.split('/').filter(Boolean);
      const langFromUrl = pathSegments[1]?.toUpperCase();
      if (langFromUrl && supported.has(langFromUrl)) {
        return langFromUrl;
      }

      return state.userStoredLocalization ?? state.plantLocalization ?? 'EN';
    },
    validTimezone(state): string {
      const fallbackTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const tz = state.plantTimezone;
      return tz && moment.tz.zone(tz) ? tz : fallbackTz;
    },
  },

  actions: {
    async fetchPlantLocalizationIfNeeded(
      umeBackend: string,
      token: string,
    ): Promise<void> {
      if (
        !this.userSelectedLocalization &&
        !this.userStoredLocalization &&
        !this.plantLocalization &&
        this.plant
      ) {
        try {
          const svc = new apiService(umeBackend, token);
          const plantDetails = await svc.getPlantDetails(this.plant);
          const newLocalizationUpper =
            plantDetails?.languageCode?.toLocaleUpperCase() ?? undefined;
          this.plantLocalization = this.availableLanguages.some(
            (lang) => lang.value === newLocalizationUpper,
          )
            ? newLocalizationUpper
            : undefined;
          if (newLocalizationUpper) {
            this.initializeUserSelection(newLocalizationUpper);
          }
        } catch (error) {
          console.error('Failed to fetch plant locale', error);
        }
      }
    },
    initializeUserSelection(newLocalization: string): void {
      if (!this.userSelectedLocalization && newLocalization) {
        this.setUserSelectedLocalization(newLocalization);
      }
    },
    installCommonMessages(
      mergeLocaleMessage: (
        locale: string,
        messages: Record<string, string>,
      ) => void,
    ): void {
      mergeLocaleMessage('en', en);
      mergeLocaleMessage('fr', fr);
    },
    setPlant(newPlant: number | undefined): void {
      this.plant = newPlant;
    },
    setPlantTimezone(newTimezone: string | undefined): void {
      this.plantTimezone = newTimezone ?? '';
    },
    setUserSelectedLocalization(newLocalization: string): void {
      const newLocalizationUpper = newLocalization.toLocaleUpperCase();
      this.userSelectedLocalization = this.availableLanguages.some(
        (lang) => lang.value === newLocalizationUpper,
      )
        ? newLocalizationUpper
        : undefined;
      sessionStorage.setItem('userSelectedLocalization', newLocalizationUpper);
    },
    setUserStoredLocalization(newLocalization: string): void {
      const newLocalizationUpper = newLocalization.toLocaleUpperCase();
      this.userStoredLocalization = this.availableLanguages.some(
        (lang) => lang.value === newLocalizationUpper,
      )
        ? newLocalizationUpper
        : undefined;
      this.initializeUserSelection(newLocalizationUpper);
    },
  },
});

